_used = set()
def gid(key):
    k = 0
    base = key
    while key in _used:
        k += 1
        key = "%s#%d" % (base, k)
    _used.add(key)
    digest = hashlib.md5(key.encode("utf-8")).digest()
    return ifcopenshell.guid.compress(str(uuid.UUID(bytes=digest[:16])))

